// Roboto Mono (SIL OFL 1.1, via @fontsource/roboto-mono 5.3.0) for code in generated PDFs
(function () {
  if (!window.pdfMake || !window.pdfMake.addVirtualFileSystem || !window.vfs) return;
  var vfs = Object.assign({}, window.vfs);
  vfs['RobotoMono-400.woff'] = '';
  vfs['RobotoMono-700.woff'] = '';
  window.pdfMake.addVirtualFileSystem(vfs);
  window.pdfMakeHasMono = true;
})();